import{_ as o,l as n,o as e,c as l,v as t,p as s,x as r,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"追踪 JIT","description":"","frontmatter":{"title":"追踪 JIT","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tracing-jit.md","filePath":"cs/tracing-jit.md","lastUpdated":1789023840000}'),h={name:"cs/tracing-jit.md"};function E(T,a,m,_,A,u){const i=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="追踪-jit" tabindex="-1">追踪 JIT <a class="header-anchor" href="#追踪-jit" aria-label="Permalink to &quot;追踪 JIT&quot;">​</a></h1><div class="epigraph"><p>记录热循环走的一条路径（trace），编译成直线代码，用守卫处理偏离。单位是路径，不是整个方法。</p><footer>—— 据 Gal, Eich et al., Trace-based Just-in-Time Type Specialization for Dynamic Languages；Bala, Duesterwald and Banerjia Dynamo 整理</footer></div><p>上一课<a href="/cs/method-jit">方法 JIT</a> 编译整个方法，含冷枝。缺口是<strong>追踪</strong>：只编译反复走的边序列，动态语言上特别有效（类型沿路径稳定）。本课钉记录、守卫、trace tree，内联缓存下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>方法里 <code>if</code> 多，编译全部浪费。Trace：从热回边开始记录字节码直到回边闭合。偏离守卫：类型或分支不同则退出到解释器。缺口是<strong>路径 IR</strong>，不是方法 CFG 全编译。</p><p>Dynamo 对 native 二进制做同类；JS 引擎曾用 TraceMonkey。</p><h3 id="追踪不是软件流水" tabindex="-1">追踪不是软件流水 <a class="header-anchor" href="#追踪不是软件流水" aria-label="Permalink to &quot;追踪不是软件流水&quot;">​</a></h3><p>软件流水是静态循环核；trace 是动态记录的路径，可跨方法调用（inlining 在记录里发生）。</p><p><span class="marginnote">Gal et al. 2009（TraceMonkey）。Dynamo 2000。SPUR、RPython 元追踪点名。本课不写元 JIT 全文。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>解释时在热循环启动 recorder。生成 SSA-like 线性 IR。编译。出口桩。嵌套循环：inner trace 或 abort。</p>',11)),(e(),s(p,null,{default:r(()=>[d(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20HOT%5B%22%E7%83%AD%E5%9B%9E%E8%BE%B9%22%5D%20--%3E%20REC%5B%22%E8%AE%B0%E5%BD%95%E8%B7%AF%E5%BE%84%22%5D%0A%20%20REC%20--%3E%20GRD%5B%22%E6%8F%92%E5%85%A5%E5%AE%88%E5%8D%AB%22%5D%0A%20%20GRD%20--%3E%20NAT%5B%22%E7%BC%96%E8%AF%91%E7%9B%B4%E7%BA%BF%E7%A0%81%22%5D%0A%20%20NAT%20--%3E%20EXIT%5B%22%E5%A4%B1%E8%B4%A5%E5%9B%9E%E8%A7%A3%E9%87%8A%E5%99%A8%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与方法 JIT：混合（HotSpot 不以 trace 为主）。路径太短或守卫太密则放弃。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>副作用：记录时已执行，编译码要等价重放——小心。异常与 GC 安全点：trace 上要能停。不要无限记录多态路径。</p><p>代码膨胀：每条热路径一份。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写去优化。后课默认：热路径可 trace 编译。下一课内联缓存：另一种投机，粒度是调用点。</p><p>也不把 trace 当分布式 tracing。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>追踪 JIT：编译热路径 + 守卫退出。</li><li>适合类型沿路径稳定的动态语言。</li><li>与方法 JIT 可混合。</li><li>出处：Gal et al.；Dynamo（Bala et al.）。</li></ul>',9))])}const D=o(h,[["render",E]]);export{f as __pageData,D as default};
